import {
  applyVersionGate,
  defineCapabilitySet,
  type AdapterCapability,
  type CapabilityEntry,
  type CapabilityKey,
  type CapabilitySet,
} from '../../capabilities.js';
import { resumeCapability } from '../../resume-verification.js';
import { CODEX_PIN } from './pins.js';

const LIVE_PENDING =
  'adapter mapping contract-tested against a fake app-server built from the protocol generated by the pinned codex-cli 0.164.0 (2026-10-26); ' +
  'live run against a model pending (REMYRAL_LIVE_RUNTIMES=1)';

/** Truthful Codex capability set (ADR-0008); nothing is `supported` before the live contract run. */
const BASE: Partial<Record<AdapterCapability, CapabilityEntry>> = {
  streaming: { status: 'unverified', reason: LIVE_PENDING },
  interactive_prompt: { status: 'unverified', reason: `turn/steer into the running turn: ${LIVE_PENDING}` },
  approval: { status: 'unverified', reason: `app-server approval requests: ${LIVE_PENDING}` },
  cancel: { status: 'unverified', reason: `turn/interrupt: ${LIVE_PENDING}` },
  resume: { status: 'unverified', reason: `thread/resume on the same worker: ${LIVE_PENDING}` },
  cost_reporting: {
    status: 'unverified',
    reason: `token usage only (no dollar cost in the protocol; the master estimates from tokens): ${LIVE_PENDING}`,
  },
  artifacts: { status: 'unverified', reason: `turn/diff/updated aggregated diff: ${LIVE_PENDING}` },
  safe_cancel: {
    status: 'unverified',
    reason:
      'the app-server process group is reaped by the worker; sandboxed tool processes outside the group are contained only by p3-sandbox',
  },
};

/** Tuples on which the credential-free real-binary smoke suite ran (test/runtimes/codex/smoke.test.ts). */
const SMOKE_VERIFIED: Readonly<Record<string, Partial<Record<AdapterCapability, CapabilityEntry>>>> = {
  'darwin-arm64': {
    cancel: {
      status: 'degraded',
      reason:
        'verified 2026-10-13 on darwin arm64: cancel ends the session and kills the app-server process tree; turn/interrupt of a running turn not yet verified live',
    },
  },
};

/**
 * p17-runtime-verify (ADR-0012 amendment 2026-10-27): what this adapter declares once a capability passed its live
 * verification scenario on an exact (version, OS, arch) — the ceiling a passed check can lift `unverified` to.
 */
export const CODEX_DECLARED_CAPABILITIES: Readonly<Record<AdapterCapability, CapabilityEntry>> = {
  streaming: { status: 'supported', reason: 'app-server item/turn notifications mapped to sequenced events' },
  interactive_prompt: { status: 'supported', reason: 'turn/steer into the running turn' },
  approval: { status: 'supported', reason: 'app-server approval requests answered with the human decision' },
  cancel: {
    status: 'supported',
    reason: 'turn/interrupt, then the app-server process tree is killed after the grace period',
  },
  resume: { status: 'degraded', reason: 'same worker only (thread/resume on the kept thread)' },
  cost_reporting: {
    status: 'degraded',
    reason: 'token usage only (no dollar cost in the protocol; the master estimates from tokens)',
  },
  artifacts: {
    status: 'degraded',
    reason: "turn/diff/updated aggregated diff; the worker's own git diff stays authoritative",
  },
  safe_cancel: {
    status: 'degraded',
    reason:
      'the app-server process group is reaped by the worker; sandboxed tool processes outside the group are contained only by the sandbox',
  },
};

/** p17-runtime-verify: bump when the adapter's mapping changes — evidence of an older revision then expires. */
export const CODEX_ADAPTER_REVISION = `codex-adapter/1+protocol${CODEX_PIN}`;

export function codexCapabilities(key: CapabilityKey): CapabilitySet {
  // p11-session-continuity: `resume` is supported only for a version whose native resume was verified live.
  const resume = resumeCapability(
    'codex',
    key.version,
    BASE.resume ?? { status: 'unverified', reason: LIVE_PENDING },
  );
  const set = defineCapabilitySet(key, { ...BASE, ...SMOKE_VERIFIED[`${key.os}-${key.arch}`], resume });
  return applyVersionGate(set, CODEX_PIN);
}
